import { OpenCallbackProps, SUBSCRIPTION_STEPS } from '@proton/components/index';
import { SelectedPlan } from '@proton/components/payments/core/subscription/selected-plan';
import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
import { isScribeAddon, removeAddon } from '@proton/shared/lib/helpers/planIDs';
import { UserModel } from '@proton/shared/lib/interfaces';

const getUpgradeCycles = (currentCycle = CYCLE.MONTHLY) => ({
    cycle: currentCycle,
    minimumCycle: currentCycle,
    maximumCycle: currentCycle === CYCLE.MONTHLY ? CYCLE.YEARLY : currentCycle,
});

// Free users are uspell to Mail Plus with the add-on
const freeUserUpsellConfig = (upsellRef: string): OpenCallbackProps => {
    const cycles = getUpgradeCycles();
    return {
        mode: 'upsell-modal',
        planIDs: { [PLANS.MAIL]: 1, [ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS]: 1 },
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        withB2CAddons: true,
        disablePlanSelection: true,
        upsellRef,
        ...cycles,
        metrics: {
            source: 'upsells',
        },
    };
};

const paidSingleUserUpsellConfig = (
    upsellRef: string,
    planName: PLANS,
    addonName: ADDON_NAMES,
    cycle?: CYCLE
): OpenCallbackProps => {
    const cycles = getUpgradeCycles(cycle);
    return {
        mode: 'upsell-modal',
        planIDs: { [planName]: 1, [addonName]: 1 },
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        withB2CAddons: true,
        disablePlanSelection: true,
        upsellRef,
        ...cycles,
        metrics: {
            source: 'upsells',
        },
    };
};

const paidMultipleUserUpsellConfig = (
    upsellRef: string,
    addonName: ADDON_NAMES,
    selectedPlan: SelectedPlan
): OpenCallbackProps => {
    const cycles = getUpgradeCycles(selectedPlan.cycle);

    // if we already have scribe addons, then we will use the current number of scribes as starting addon number
    // in the upsell
    // if we don't, then we will use the number of members as starting number for scribe addons
    const addonsValue = selectedPlan.getTotalScribes() || selectedPlan.getTotalMembers();

    return {
        mode: 'upsell-modal',
        planIDs: {
            ...selectedPlan.planIDs,
            [addonName]: addonsValue,
        },
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        withB2CAddons: true,
        disablePlanSelection: true,
        upsellRef,
        ...cycles,
        metrics: {
            source: 'upsells',
        },
    };
};

export const paidUserAssistantAddonName = (planName?: PLANS) => {
    switch (planName) {
        case PLANS.MAIL:
            return ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS;
        case PLANS.DRIVE:
            return ADDON_NAMES.MEMBER_SCRIBE_DRIVEPLUS;
        case PLANS.BUNDLE:
            return ADDON_NAMES.MEMBER_SCRIBE_BUNDLE;
        case PLANS.PASS_PLUS:
            return ADDON_NAMES.MEMBER_SCRIBE_PASS;
        case PLANS.VPN:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN;
        case PLANS.VPN2024:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN2024;
        case PLANS.VPN_PASS_BUNDLE:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN_PASS_BUNDLE;
        case PLANS.MAIL_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO;
        case PLANS.BUNDLE_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO;
        case PLANS.BUNDLE_PRO_2024:
            return ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO_2024;
        case PLANS.MAIL_BUSINESS:
            return ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS;
        case PLANS.PASS_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_PASS_PRO;
        case PLANS.VPN_BUSINESS:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN_BIZ;
        case PLANS.PASS_BUSINESS:
            return ADDON_NAMES.MEMBER_SCRIBE_PASS_BIZ;
        case PLANS.VPN_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN_PRO;
        case PLANS.FAMILY:
            return ADDON_NAMES.MEMBER_SCRIBE_FAMILY;
        default:
            return ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS;
    }
};

export const getAssistantUpsellConfig = (
    upsellRef: string,
    user: UserModel,
    isOrgAdmin: boolean,
    selectedPlan: SelectedPlan
): OpenCallbackProps | undefined => {
    if (user.isSubUser) {
        return undefined;
    }

    if (isOrgAdmin) {
        const addonName = paidUserAssistantAddonName(selectedPlan.name);
        return paidMultipleUserUpsellConfig(upsellRef, addonName, selectedPlan);
    }

    if (user.isPaid) {
        const addonName = paidUserAssistantAddonName(selectedPlan.name);
        return paidSingleUserUpsellConfig(upsellRef, selectedPlan.name, addonName, selectedPlan.cycle);
    }

    // Return the free user config if the user is not paid and don't have member in its organization
    return freeUserUpsellConfig(upsellRef);
};

export const getAssistantDowngradeConfig = (
    upsellRef: string,
    selectedPlan: SelectedPlan
): OpenCallbackProps | undefined => {
    return {
        mode: 'upsell-modal',
        /**
         * Removes only Scribe addons and keep all others
         */
        planIDs: removeAddon(selectedPlan.planIDs, isScribeAddon),
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        disablePlanSelection: true,
        cycle: selectedPlan.cycle,
        maximumCycle: selectedPlan.cycle,
        minimumCycle: selectedPlan.cycle,
        upsellRef,
        metrics: {
            source: 'upsells',
        },
    };
};
import { SelectedPlan } from '@proton/components/payments/core/subscription/selected-plan';
import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
import { UserModel } from '@proton/shared/lib/interfaces';
import { PLANS_MAP } from '@proton/testing/data';

import { SUBSCRIPTION_STEPS } from '../..';
import { getAssistantUpsellConfig } from './assistantUpsellConfig';

const baseConfig: any = {
    mode: 'upsell-modal',
    planIDs: { [PLANS.MAIL]: 1, [ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS]: 1 },
    step: SUBSCRIPTION_STEPS.CHECKOUT,
    disablePlanSelection: true,
    upsellRef: 'upsellRef',
    metrics: {
        source: 'upsells',
    },
};

describe('getAssistantUpsellConfig', () => {
    it('should return undefined if the user is a sub user', () => {
        const user = {
            isSubUser: true,
        } as unknown as UserModel;
        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');

        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual(undefined);
    });

    it('should return free user config if the user is free without a subscription', () => {
        const user = {
            isPaid: false,
        } as unknown as UserModel;
        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            cycle: CYCLE.MONTHLY,
            maximumCycle: CYCLE.YEARLY,
            minimumCycle: CYCLE.MONTHLY,
            withB2CAddons: true,
        });
    });

    it('should return paid config with yearly and monthly cycles if the user is paid with monthly billing', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;
        const selectedPlan = new SelectedPlan({ [PLANS.MAIL]: 1 }, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.MONTHLY,
            maximumCycle: CYCLE.YEARLY,
            minimumCycle: CYCLE.MONTHLY,
            withB2CAddons: true,
        });
    });

    it('should return paid config with only yearly cycle if the user is paid with yearly billing', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;
        const selectedPlan = new SelectedPlan({ [PLANS.MAIL]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'EUR');

        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.YEARLY,
            maximumCycle: CYCLE.YEARLY,
            minimumCycle: CYCLE.YEARLY,
            withB2CAddons: true,
        });
    });

    it('should return paid config with only two years if the user is paid with two years billing', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;

        const selectedPlan = new SelectedPlan({ [PLANS.MAIL]: 1 }, PLANS_MAP, CYCLE.TWO_YEARS, 'EUR');

        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.TWO_YEARS,
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
        });
    });

    // TODO this will probably not be right
    it('should return paid config if the user is paid with family plan', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;

        const selectedPlan = new SelectedPlan(
            {
                [PLANS.FAMILY]: 1,
            },
            PLANS_MAP,
            CYCLE.TWO_YEARS,
            'EUR'
        );

        const config = getAssistantUpsellConfig('upsellRef', user, false, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.TWO_YEARS,
            planIDs: { [PLANS.FAMILY]: 1, [ADDON_NAMES.MEMBER_SCRIBE_FAMILY]: 1 },
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
        });
    });

    it('should return multi config with max members if the user has member but no MaxAI', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;

        const selectedPlan = new SelectedPlan(
            {
                [PLANS.MAIL_PRO]: 1,
                [ADDON_NAMES.MEMBER_MAIL_PRO]: 4,
            },
            PLANS_MAP,
            CYCLE.TWO_YEARS,
            'EUR'
        );

        const config = getAssistantUpsellConfig('upsellRef', user, true, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.TWO_YEARS,
            planIDs: { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 4, [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 5 },
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
        });
    });

    it('should return multi config with max AI if the user has member and MaxAI', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;

        const selectedPlan = new SelectedPlan(
            {
                [PLANS.MAIL_PRO]: 1,
                [ADDON_NAMES.MEMBER_MAIL_PRO]: 4,
                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 2,
            },
            PLANS_MAP,
            CYCLE.TWO_YEARS,
            'EUR'
        );

        const config = getAssistantUpsellConfig('upsellRef', user, true, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.TWO_YEARS,
            planIDs: { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 4, [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 2 },
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
        });
    });

    it('should return multi config with all existing if the user has member and MaxAI', () => {
        const user = {
            isPaid: true,
        } as unknown as UserModel;

        const selectedPlan = new SelectedPlan(
            {
                [PLANS.MAIL_PRO]: 1,
                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
                [ADDON_NAMES.MEMBER_MAIL_PRO]: 4,
                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 2,
            },
            PLANS_MAP,
            CYCLE.TWO_YEARS,
            'EUR'
        );

        const config = getAssistantUpsellConfig('upsellRef', user, true, selectedPlan);

        expect(config).toEqual({
            ...baseConfig,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: CYCLE.TWO_YEARS,
            planIDs: {
                [PLANS.MAIL_PRO]: 1,
                [ADDON_NAMES.MEMBER_MAIL_PRO]: 4,
                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 2,
            },
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
        });
    });
});

